def _solve(arr):
    start = tuple(arr)
    dist = {start: 0}
    q = deque([start])
    while q:
        s = q.popleft()
        if len(s) == 0:
            return dist[s]
        d = dist[s]
        nbrs = []
        for i in range(len(s) - 1):
            l = list(s)
            l[i], l[i + 1] = l[i + 1], l[i]
            nbrs.append(tuple(l))
        for i in range(1, len(s) + 1):
            if s[i - 1] != s[0]:
                break
            nbrs.append(s[i:])
        for ns in nbrs:
            if ns not in dist:
                dist[ns] = d + 1
                q.append(ns)
    return -1

